begin;create extension if not exists pgtap with schema extensions;select plan(24);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values
('00000000-0000-0000-0000-000000000000','99900000-0000-4000-8000-000000000060','authenticated','authenticated','recommendation-owner@example.test','',now(),now(),now()),
('00000000-0000-0000-0000-000000000000','99900000-0000-4000-8000-000000000061','authenticated','authenticated','recommendation-limited@example.test','',now(),now(),now());
set local role authenticated;select set_config('request.jwt.claim.sub','99900000-0000-4000-8000-000000000060',true);select set_config('request.jwt.claims','{"sub":"99900000-0000-4000-8000-000000000060","role":"authenticated"}',true);
select public.create_business('recommendation-test','Recommendation Test Inc','Recommendation Test','sole_proprietorship','retail','{"city":"Manila"}');select set_config('test.recommendation_org',(select id::text from public.organizations where slug='recommendation-test'),true);select set_config('test.recommendation_branch',(select id::text from public.branches where organization_id=current_setting('test.recommendation_org')::uuid),true);select set_config('test.recommendation_version',(select version.id::text from public.business_os_template_versions version join public.business_os_templates template on template.id=version.template_id where template.key='retail-store-os'and version.status='published'order by version.version desc limit 1),true);select public.install_business_os_template(current_setting('test.recommendation_org')::uuid,current_setting('test.recommendation_version')::uuid);select public.set_business_module_state(current_setting('test.recommendation_org')::uuid,'product_catalog',true,'{}');select public.set_business_module_state(current_setting('test.recommendation_org')::uuid,'inventory',true,'{}');select public.set_business_module_state(current_setting('test.recommendation_org')::uuid,'expenses',true,'{}');
select set_config('test.recommendation_location',(select id::text from public.inventory_locations where organization_id=current_setting('test.recommendation_org')::uuid),true);select set_config('test.recommendation_product',public.save_catalog_product(current_setting('test.recommendation_org')::uuid,null,null,'product','Forecast Nails','',null,null,'box',100,60,'exclusive',0,'active',false,'[{"name":"Box","sku":"REC-1","attributes":{},"status":"active"}]','[]')::text,true);select set_config('test.recommendation_variant',(select id::text from public.product_variants where product_id=current_setting('test.recommendation_product')::uuid),true);select set_config('test.recommendation_item',public.configure_inventory_item(current_setting('test.recommendation_org')::uuid,null,current_setting('test.recommendation_variant')::uuid,10,25,true)::text,true);select public.record_stock_movement(current_setting('test.recommendation_org')::uuid,current_setting('test.recommendation_item')::uuid,current_setting('test.recommendation_location')::uuid,'opening_balance',20,60,'Opening','recommendation-opening-1');select set_config('test.recommendation_category',public.save_expense_category(current_setting('test.recommendation_org')::uuid,null,'Operations','Test',true)::text,true);
select set_config('test.recommendation_customer',gen_random_uuid()::text,true);select set_config('test.recommendation_sale_a',gen_random_uuid()::text,true);select set_config('test.recommendation_sale_b',gen_random_uuid()::text,true);
reset role;insert into public.sales_customers(id,organization_id,branch_id,name,phone,transaction_count,total_spend,last_transaction_at)values(current_setting('test.recommendation_customer')::uuid,current_setting('test.recommendation_org')::uuid,current_setting('test.recommendation_branch')::uuid,'Top Customer','+639171234567',1,400,now());
insert into public.sales_transactions(id,organization_id,branch_id,inventory_location_id,customer_id,receipt_number,status,total,amount_paid,currency,client_transaction_id,client_created_at,completed_at,created_by,created_at)values
(current_setting('test.recommendation_sale_a')::uuid,current_setting('test.recommendation_org')::uuid,current_setting('test.recommendation_branch')::uuid,current_setting('test.recommendation_location')::uuid,current_setting('test.recommendation_customer')::uuid,'REC-A','completed',400,400,'PHP',gen_random_uuid(),now(),now(),'99900000-0000-4000-8000-000000000060',now()),
(current_setting('test.recommendation_sale_b')::uuid,current_setting('test.recommendation_org')::uuid,current_setting('test.recommendation_branch')::uuid,current_setting('test.recommendation_location')::uuid,null,'REC-B','completed',600,600,'PHP',gen_random_uuid(),now(),now(),'99900000-0000-4000-8000-000000000060',now());
