(current_setting('test.recommendation_org')::uuid,current_setting('test.recommendation_sale_a')::uuid,current_setting('test.recommendation_variant')::uuid,current_setting('test.recommendation_item')::uuid,'Forecast Nails','Box','REC-1',60,6.6667,400,0,400,3),
(current_setting('test.recommendation_org')::uuid,current_setting('test.recommendation_sale_b')::uuid,current_setting('test.recommendation_variant')::uuid,current_setting('test.recommendation_item')::uuid,'Forecast Nails','Box','REC-1',1,600,600,0,600,600);
insert into public.expenses(organization_id,expense_number,expense_date,category_id,branch_id,supplier_payee,amount,payment_method,approval_status,idempotency_key,created_by)values
(current_setting('test.recommendation_org')::uuid,'EXP-CURRENT',current_date,current_setting('test.recommendation_category')::uuid,current_setting('test.recommendation_branch')::uuid,'Current Supplier',2000,'cash','approved','rec-current','99900000-0000-4000-8000-000000000060'),
(current_setting('test.recommendation_org')::uuid,'EXP-PREVIOUS',date_trunc('month',current_date)::date-1,current_setting('test.recommendation_category')::uuid,current_setting('test.recommendation_branch')::uuid,'Previous Supplier',1000,'cash','approved','rec-previous','99900000-0000-4000-8000-000000000060');
set local role authenticated;select set_config('request.jwt.claim.sub','99900000-0000-4000-8000-000000000060',true);select set_config('request.jwt.claims','{"sub":"99900000-0000-4000-8000-000000000060","role":"authenticated"}',true);
select results_eq($$select count(*)from public.recommendation_business_query_definitions where is_enabled$$,$$select 3::bigint$$,'Recommendation query registry is bounded');
select is((public.query_recommendation_business_data(current_setting('test.recommendation_org')::uuid,'customer_sales_concentration')#>>'{rows,0,sharePercent}')::numeric,40::numeric,'Top-customer concentration is calculated from net recorded sales');
select is((public.query_recommendation_business_data(current_setting('test.recommendation_org')::uuid,'inventory_stockout_risk')#>>'{rows,0,productName}'),'Forecast Nails','Stock risk identifies the source-backed product');
select is((public.query_recommendation_business_data(current_setting('test.recommendation_org')::uuid,'inventory_stockout_risk')#>>'{rows,0,projectionDays}')::integer,7,'Stock risk uses the declared seven-day projection');
select is((public.query_recommendation_business_data(current_setting('test.recommendation_org')::uuid,'expense_period_comparison')#>>'{rows,0,changePercent}')::numeric,100::numeric,'Expense comparison uses the preceding equal-length period');
select throws_ok($$select public.query_recommendation_business_data(current_setting('test.recommendation_org')::uuid,'raw_database')$$,'22023','Unknown or unavailable recommendation query.','Arbitrary recommendation queries are rejected');
select throws_ok($$select public.query_recommendation_business_data(current_setting('test.recommendation_org')::uuid,'inventory_stockout_risk',current_date-29,current_date)$$,'22023','This projection uses a fixed trailing 30-day window and does not accept date filters.','Fixed projection rejects misleading dates');
select is(public.save_ai_recommendations(current_setting('test.recommendation_org')::uuid,null,'[{"ruleKey":"inventory_stockout_risk_7d","type":"inventory","title":"One product may reach minimum stock","summary":"Projection summary","reason":"Recorded rate and stock","supportingMetrics":[{"source":"business_query","key":"inventory_stockout_risk","data":{"queryKey":"inventory_stockout_risk"}}],"priority":"high","potentialAction":"Review replenishment","evidenceFingerprint":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}]'),1,'A traceable recommendation is saved');
select results_eq($$select status from public.ai_recommendations where organization_id=current_setting('test.recommendation_org')::uuid$$,$$select 'new'::text$$,'New recommendations start in new status');
select ok((select'recommendation.inventory.read'=any(array(select'recommendation.'||permission from unnest(required_permissions)permission))from public.ai_recommendations where organization_id=current_setting('test.recommendation_org')::uuid),'Inventory permission provenance is derived from evidence');
select ok((select'recommendation.sales.read'=any(array(select'recommendation.'||permission from unnest(required_permissions)permission))from public.ai_recommendations where organization_id=current_setting('test.recommendation_org')::uuid),'Sales permission provenance is derived from multi-source evidence');
select is(public.save_ai_recommendations(current_setting('test.recommendation_org')::uuid,null,'[{"ruleKey":"inventory_stockout_risk_7d","type":"inventory","title":"One product may reach minimum stock","summary":"Projection summary","reason":"Recorded rate and stock","supportingMetrics":[{"source":"business_query","key":"inventory_stockout_risk","data":{"queryKey":"inventory_stockout_risk"}}],"priority":"high","potentialAction":"Review replenishment","evidenceFingerprint":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}]'),0,'Evidence fingerprint makes generation idempotent');
select set_config('test.recommendation_id',(select id::text from public.ai_recommendations where organization_id=current_setting('test.recommendation_org')::uuid),true);
select lives_ok($$select public.transition_ai_recommendation(current_setting('test.recommendation_org')::uuid,current_setting('test.recommendation_id')::uuid,'viewed')$$,'New recommendation can be viewed');
select lives_ok($$select public.transition_ai_recommendation(current_setting('test.recommendation_org')::uuid,current_setting('test.recommendation_id')::uuid,'accepted')$$,'Viewed recommendation can be accepted');
select lives_ok($$select public.transition_ai_recommendation(current_setting('test.recommendation_org')::uuid,current_setting('test.recommendation_id')::uuid,'completed')$$,'Accepted recommendation can be completed');
select is((select status from public.ai_recommendations where id=current_setting('test.recommendation_id')::uuid),'completed','Lifecycle reaches completed');
select results_eq($$select count(*)from public.ai_recommendation_events where recommendation_id=current_setting('test.recommendation_id')::uuid$$,$$select 4::bigint$$,'Generation and every lifecycle change are audited');
select throws_ok($$select public.transition_ai_recommendation(current_setting('test.recommendation_org')::uuid,current_setting('test.recommendation_id')::uuid,'dismissed')$$,'22023','Invalid recommendation status transition.','Terminal status cannot be changed');
select throws_ok($$insert into public.ai_recommendations(organization_id,rule_key,recommendation_type,title,summary,reason,supporting_metrics,required_permissions,priority,potential_action,evidence_fingerprint,created_by)values(current_setting('test.recommendation_org')::uuid,'bypass','inventory','Bypass','Bypass','Bypass','[]','{inventory.read}','low','Bypass','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb','99900000-0000-4000-8000-000000000060')$$,'42501','permission denied for table ai_recommendations','Clients cannot bypass recommendation RPCs');
select throws_ok($$select public.save_ai_recommendations(current_setting('test.recommendation_org')::uuid,null,'[{"ruleKey":"bad","type":"inventory","title":"Bad","summary":"Bad","reason":"Bad","supportingMetrics":[{"source":"metric","key":"raw_sql","data":{"metricKey":"raw_sql"}}],"priority":"low","potentialAction":"None","evidenceFingerprint":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc"}]')$$,'22023','Unknown recommendation evidence.','Unknown evidence keys are rejected');
select set_config('test.recommendation_role',public.create_custom_role(current_setting('test.recommendation_org')::uuid,'recommendation_viewer','Recommendation viewer','',array['organization.read','branch.read','ai.read','report.read'])::text,true);reset role;insert into public.organization_memberships(organization_id,user_id,status,joined_at,branch_access_mode)values(current_setting('test.recommendation_org')::uuid,'99900000-0000-4000-8000-000000000061','active',now(),'all');insert into public.membership_roles(membership_id,role_id)select membership.id,current_setting('test.recommendation_role')::uuid from public.organization_memberships membership where membership.organization_id=current_setting('test.recommendation_org')::uuid and membership.user_id='99900000-0000-4000-8000-000000000061';
set local role authenticated;select set_config('request.jwt.claim.sub','99900000-0000-4000-8000-000000000061',true);select set_config('request.jwt.claims','{"sub":"99900000-0000-4000-8000-000000000061","role":"authenticated"}',true);
select results_eq($$select count(*)from public.ai_recommendations where organization_id=current_setting('test.recommendation_org')::uuid$$,$$select 0::bigint$$,'A user without source permissions cannot see recommendation evidence');
select throws_ok($$select public.query_recommendation_business_data(current_setting('test.recommendation_org')::uuid,'inventory_stockout_risk')$$,'42501','Permission denied.','A user cannot run recommendation queries without source permissions');
select throws_ok($$select public.save_ai_recommendations(current_setting('test.recommendation_org')::uuid,null,'[]')$$,'42501','Permission denied.','AI read permission cannot generate recommendations');
select throws_ok($$select public.transition_ai_recommendation(current_setting('test.recommendation_org')::uuid,current_setting('test.recommendation_id')::uuid,'viewed')$$,'42501','Permission denied.','A user without evidence access cannot transition a recommendation');
select*from finish();rollback;
